def countSubstrings(s):
    ans=0
    digits=[int(c) for c in s]
    prefix_mod=[0]*10
    freq=[None]*10
    for d in range(1,10):
        freq[d]=[0]*d
        freq[d][0]=1
    for idx,digit in enumerate(digits):
        for d in range(1,10):
            prefix_mod[d]=(prefix_mod[d]*10+digit)%d
        if digit!=0:
            d=digit
            ans+=freq[d][prefix_mod[d]]
        for d in range(1,10):
            freq[d][prefix_mod[d]]+=1
    return ans

