    cnt_var_before=0
    for i in range(N):
        q_after=suff[i+1]
        if B[i]==-1:
            total=0
            K=min_fixed_before-1
            if K>0:
                for x in range(1,K+1):
                    v=M-x
                    total=(total+pow_of_val[v][cnt_var_before])%MOD
            # else total=0
            contrib= total*pow_M[q_after]%MOD
            ans=(ans+contrib)%MOD
        else:
            x=B[i]
            if min_fixed_before<=x:
                count_before=0
