def count_components(A):
    N=len(A)
    parent=list(range(N))
    def find(x):
        while parent[x]!=x:
            parent[x]=parent[parent[x]]
            x=parent[x]
        return x
    def union(x,y):
        rx,ry=find(x),find(y)
        if rx!=ry:
            parent[ry]=rx
    for i in range(N):
