import heapq

def min_operations(nums:List[int], x:int, k:int)->int:
    N=len(nums)
    low=[];high=[];low_remove={};high_remove={};cnt_low=cnt_high=0;sum_low=sum_high=0
    def clean_low():
        nonlocal low, low_remove, cnt_low
        while low:
            val=-low[0]
            if low_remove.get(val,0):
                low_remove[val]-=1
                if low_remove[val]==0: del low_remove[val]
                heapq.heappop(low); cnt_low-=1
            else: break
    def clean_high():
        nonlocal high, high_remove, cnt_high
        while high:
            val=high[0]
            if high_remove.get(val,0):
                high_remove[val]-=1
                if high_remove[val]==0: del high_remove[val]
                heapq.heappop(high); cnt_high-=1
            else: break
    def balance():
        nonlocal low,high,cnt_low,cnt_high,sum_low,sum_high
        clean_low(); clean_high()
        while cnt_low < cnt_high:
            clean_high(); val=heapq.heappop(high); sum_high-=val; cnt_high-=1; heapq.heappush(low,-val); sum_low+=val; cnt_low+=1; clean_low()
        while cnt_low > cnt_high+1:
            clean_low(); val=-heapq.heappop(low); sum_low-=val; cnt_low-=1; heapq.heappush(high,val); sum_high+=val; cnt_high+=1; clean_high()
    def add(val:int):
        nonlocal low,high,cnt_low,cnt_high,sum_low,sum_high
        if not low:
            heapq.heappush(low,-val); sum_low+=val; cnt_low+=1
        else:
            median=-low[0]
            if val<=median:
                heapq.heappush(low,-val); sum_low+=val; cnt_low+=1
            else:
                heapq.heappush(high,val); sum_high+=val; cnt_high+=1
        balance()
    def remove(val:int):
        nonlocal low,high,cnt_low,cnt_high,sum_low,sum_high
        clean_low(); clean_high()
        median=-low[0] if low else None
        if median is not None and val<=median:
            cnt_low-=1; sum_low-=val; low_remove[val]=low_remove.get(val,0)+1
        else:
            cnt_high-=1; sum_high-=val; high_remove[val]=high_remove.get(val,0)+1
        balance()
    def cur_cost():
        clean_low(); clean_high()
        median=-low[0]
        return median*cnt_low - sum_low + sum_high - median*cnt_high
    costs=[0]*N
    w=0
    for i in range(N):
        add(nums[i]); w+=1
        if w> x:
            remove(nums[i-x]); w-=1
        if w==x:
            s=i-x+1
            costs[s]=cur_cost()
    INF=10**18
    dp=[[INF]*(k+1) for _ in range(N+1)]
    dp[0][0]=0
    for i in range(1,N+1):
        dp[i][0]=0
        for j in range(1,k+1):
            dp[i][j]=dp[i-1][j]
            if i>=x:
                s=i-x
                dp[i][j]=min(dp[i][j], dp[s][j-1] + costs[s])
    return dp[N][k]

