def fast(arr):
    from collections import defaultdict
    groups=defaultdict(list)
    for a in arr:
        k=0
        while a%2==0:
            a//=2
            k+=1
        groups[k].append(a)
    size={}
    sum_u={}
    for k, lst in groups.items():
        size[k]=len(lst)
        sum_u[k]=sum(lst)
    ans=0
    for k, sz in size.items():
        s=sum_u[k]
        ans+=s  # self
        ans+= (sz-1)*s  # within
    ks=sorted(size.keys())
    for i in range(len(ks)):
        for j in range(i+1,len(ks)):
            k_low=ks[i]; k_high=ks[j]
            delta=k_high-k_low
            ans+= size[k_high]*sum_u[k_low]
            ans+= size[k_low]*sum_u[k_high]*(1<<delta)
    return ans

