"""
Solution for: maximize-the-distance-between-points-on-a-square
Problem ID: lcb_3781

Implement the function below.
"""

from typing import List
import bisect

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        C = 4 * side
        t = []
        for x, y in points:
            if x == 0:
                pos = y
            elif y == side:
                pos = side + x
            elif x == side:
                pos = 2 * side + (side - y)
            elif y == 0:
                pos = 3 * side + (side - x)
            else:
                continue
            t.append(pos)
        n = len(t)
        if k <= 1:
            return C
        t.sort()
        t_ext = t + [x + C for x in t]

        def can(D: int) -> bool:
            for start in range(n):
                last = t_ext[start]
                count = 1
                idx = start
                while count < k:
                    target = last + D
                    l = idx + 1
                    r = start + n
                    nxt = bisect.bisect_left(t_ext, target, l, r)
                    if nxt >= r:
                        break
                    last = t_ext[nxt]
                    idx = nxt
                    count += 1
                if count == k:
                    return True
            return False

        low, high = 0, C + 1
        while low + 1 < high:
            mid = (low + high) // 2
            if can(mid):
                low = mid
            else:
                high = mid
        return low

