import random

def brute(N, X, Us, Ds):
    best = 0
    maxH = min(u+d for u,d in zip(Us,Ds))
    for H in range(maxH+1):
        values=[list(range(max(0, H-Ds[i]), min(Us[i], H)+1)) for i in range(N)]
        def dfs(idx, prev):
            if idx==N:
                return True
            for val in values[idx]:
                if idx==0 or abs(val-prev)<=X:
                    if dfs(idx+1, val):
                        return True
            return False
        if dfs(0,0):
            best = H
    return sum(Us)+sum(Ds)-N*best

def fast(N,X,Us,Ds):
    tot=sum(Us)+sum(Ds)
    maxH=min(u+d for u,d in zip(Us,Ds))
    lo,hi=0,maxH
    def feasible(H):
        low=max(0,H-Ds[0])
        high=min(Us[0],H)
        if low>high: return False
        for i in range(1,N):
            low=max(low - X, 0, H-Ds[i])
            high=min(high + X, Us[i], H)
            if low>high: return False
        return True
    best=0
    while lo<=hi:
        mid=(lo+hi)//2
        if feasible(mid):
            best=mid
            lo=mid+1
        else:
            hi=mid-1
    return tot - N*best

for _ in range(200):
    N=random.randint(2,5)
    X=random.randint(1,5)
    Us=[random.randint(1,10) for _ in range(N)]
    Ds=[random.randint(1,10) for _ in range(N)]
