    low = 0
    high = maxH
    def feasible(H: int) -> bool:
        # interval for U'_i values
        low_i = max(H - Ds[0], 0)
        high_i = min(Us[0], H)
        if low_i > high_i:
            return False
        for i in range(1, N):
