            nx, ny = x, y + c
        elif d == 'D':
            nx, ny = x, y - c
        elif d == 'L':
            nx, ny = x - c, y
        else:  # 'R'
            nx, ny = x + c, y
        if d in ('U','D'):
            # vertical segment on column x
            y1, y2 = sorted((y, ny))
            col_segs[x].append((y1, y2))
