import sys

MOD = 998244353

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    s = data[1]

    match = [0] * n
    stack = []
    for i, ch in enumerate(s):
        if ch == '(':
            stack.append(i)
        else:
            l = stack.pop()
            match[l] = i
            match[i] = l

    children = [[] for _ in range(n)]
    for open_pos in range(n):
        if s[open_pos] != '(':
            continue
        close_pos = match[open_pos]
        cur = open_pos + 1
        while cur < close_pos:
            children[open_pos].append(cur)
            cur = match[cur] + 1

    tops = []
    cur = 0
    while cur < n:
        tops.append(cur)
        cur = match[cur] + 1

    max_k = max(len(tops), max((len(v) for v in children), default=0))
    fact = [1] * (max_k + 1)
    for i in range(1, max_k + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact = [1] * (max_k + 1)
    invfact[max_k] = pow(fact[max_k], MOD - 2, MOD)
    for i in range(max_k, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    memo = {}
    def dfs(open_pos):
        if open_pos in memo:
            return memo[open_pos]
        child_reps = []
        total = 1
        for ch in children[open_pos]:
            rep_child, contrib_child = dfs(ch)
            child_reps.append(rep_child)
            total = total * contrib_child % MOD
