        total = total * perm % MOD
        rep_str = '(' + ''.join(child_reps) + ')'
        memo[open_pos] = (rep_str, total)
        return memo[open_pos]

    root_child_reps = []
    total_root = 1
    for top in tops:
        rep_top, contrib_top = dfs(top)
        root_child_reps.append(rep_top)
        total_root = total_root * contrib_top % MOD
