import itertools, math
def bfs_dist(n, edges):
    from collections import deque
    adj=[[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)
    dist=[-1]*n
    dist[0]=0
    q=deque([0])
    while q:
        u=q.popleft()
        for v in adj[u]:
            if dist[v]==-1:
                dist[v]=dist[u]+1
                q.append(v)
    return dist

def parity_ok(n,edges):
    d=bfs_dist(n,edges)
    return sum(1 for i in range(n) if d[i]%2==0)==sum(1 for i in range(n) if d[i]%2==1)

