def min_cost_perm(p):
    n=len(p)
    start=tuple(p)
    target=tuple(sorted(p))
    from heapq import heappush, heappop
    dist={start:0}
    h=[(0,start)]
    while h:
        d, state=heappop(h)
        if d!=dist[state]: continue
        if state==target: return d
        for i in range(n-1):
            new=list(state)
            new[i],new[i+1]=new[i+1],new[i]
            newt=tuple(new)
            nd=d+(i+1)  # extra: i indexes 0-based; cost is 1-based
            if nd<dist.get(newt,1e18):
                dist[newt]=nd
                heappush(h,(nd,newt))
    return None

