def crossing_cost(p):
    n=len(p)
    init=[0]*(n+1)
    for i,v in enumerate(p,1):
        init[v]=i
    # fenwick for counting number of elements seen so far relative to target positions
    bit=[0]*(n+1)
    def add(i,delta):
        while i<=n:
            bit[i]+=delta
            i+=i&-i
    def sumi(i):
        s=0
        while i>0:
            s+=bit[i]
            i-=i&-i
        return s
    cost=0
    crossings=[0]*(n)
    # We'll process values ascending maybe
    # We'll compute for each boundary i
    # Approach: for each element v, determine its crossing contribution to each boundary.
    # That is O(N^2). Let's brute for small n.
    for v in range(1,n+1):
        init_pos=init[v]
        target_pos=v
        if init_pos>target_pos:
            # crosses leftwards from positions target_pos+1..init_pos
            for i in range(target_pos, init_pos):
                crossings[i]+=1
        elif init_pos<target_pos:
            # crosses rightwards from init_pos..target_pos-1
            for i in range(init_pos, target_pos):
                crossings[i]+=1
    # no crossing if equal
    total=sum((i+1)*crossings[i] for i in range(n-1))
    return total

