from typing import List

class Solution:
    def minimumCost(self, nums: List[int], cost: List[int], k: int) -> int:
        n = len(nums)
        S = [0] * (n + 1)
        C = [0] * (n + 1)
        for i in range(n):
            S[i + 1] = S[i] + nums[i]
            C[i + 1] = C[i] + cost[i]
        INF = 10 ** 18
        dp = [[INF] * (n + 1) for _ in range(n + 1)]
        dp[0][0] = 0
        for i in range(1, n + 1):
            for t in range(1, i + 1):
                best = INF
                for j in range(t - 1, i):
                    if dp[j][t - 1] == INF:
                        continue
                    cur = dp[j][t - 1] + (S[i] - S[j] + k * t) * (C[i] - C[j])
                    if cur < best:
                        best = cur
                dp[i][t] = best
        return min(dp[n][1:])

if __name__ == "__main__":
    sol = Solution()
    print(sol.minimumCost([3,1,4], [4,6,6], 1))
    print(sol.minimumCost([4,8,5,1,14,2,2,12,1], [7,2,8,4,2,2,1,1,2], 7))
