import sys
from typing import List

class SegTree:
    def __init__(self, base):
        self.n = len(base)
        N = 1
        while N < self.n:
            N <<= 1
        self.N = N
        self.data = [-10**9] * (2 * N)
        self.lazy = [0] * (2 * N)
        for i in range(self.n):
            self.data[N + i] = base[i]
        for i in range(N - 1, 0, -1):
            self.data[i] = max(self.data[2 * i], self.data[2 * i + 1])
    def _apply(self, idx, val):
        self.data[idx] += val
        self.lazy[idx] += val
    def _push(self, idx):
        if self.lazy[idx]:
            self._apply(idx * 2, self.lazy[idx])
            self._apply(idx * 2 + 1, self.lazy[idx])
            self.lazy[idx] = 0
    def range_add(self, l, r, val):
        def _add(idx, left, right):
            if l <= left and right <= r:
                self._apply(idx, val)
                return
            self._push(idx)
            mid = (left + right) // 2
            if l <= mid:
                _add(idx * 2, left, mid)
            if r > mid:
                _add(idx * 2 + 1, mid + 1, right)
            self.data[idx] = max(self.data[idx * 2], self.data[idx * 2 + 1])
        _add(1, 0, self.N - 1)
    def range_max(self, l, r):
        def _query(idx, left, right):
            if l <= left and right <= r:
                return self.data[idx]
            self._push(idx)
            mid = (left + right) // 2
            res = -10**9
            if l <= mid:
                res = max(res, _query(idx * 2, left, mid))
            if r > mid:
                res = max(res, _query(idx * 2 + 1, mid + 1, right))
            return res
        return _query(1, 0, self.N - 1)

def solve_instance(N, A):
    A = [0] + A
    pref = [0] * (N + 1)
    seen = set()
    for i in range(1, N + 1):
        if A[i] not in seen:
            pref[i] = pref[i - 1] + 1
            seen.add(A[i])
        else:
            pref[i] = pref[i - 1]
    prev = [0] * (N + 1)
    last = dict()
    for i in range(1, N + 1):
        prev[i] = last.get(A[i], 0)
        last[A[i]] = i
    suff = [0] * (N + 3)
    seen = set()
    for i in range(N, 0, -1):
        if A[i] not in seen:
            suff[i] = suff[i + 1] + 1
            seen.add(A[i])
        else:
            suff[i] = suff[i + 1]
    base = pref
    st = SegTree(base)
    ans = 0
    for j in range(1, N):
        p = prev[j]
        st.range_add(p, N, 1)
        best_left = st.range_max(0, j - 1)
        ans = max(ans, best_left + suff[j + 1])
    return ans

