"""
Solution for: maximum-product-of-subsequences-with-an-alternating-sum-equal-to-k
Problem ID: lcb_3777

Implement the function below.
"""

from typing import List


class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # DP state: mapping from (sum, parity) to (max_product, has_elem)
        # parity: 0 -> next element would be at even position in subsequence,
        # 1 -> next would be odd. We start with parity 0.
        dp: dict[tuple[int, int], tuple[int, bool]] = {(0, 0): (1, False)}

        for num in nums:
            new_dp = dict(dp)  # copy existing states (skip this num)
            for (s, p), (prod, has) in dp.items():
                # adding this num to subsequence
                if p == 0:
                    new_sum = s + num
                else:
                    new_sum = s - num
                new_parity = 1 - p
                new_prod = prod * num
                if new_prod > limit:
                    continue
                key = (new_sum, new_parity)
                curr_prod, curr_has = new_dp.get(key, (0, False))
                # we prefer larger product; if equal, we don't care about has flag
                if new_prod > curr_prod or (new_prod == curr_prod and (has or curr_has)):
                    new_dp[key] = (new_prod, True)
            dp = new_dp

        best = -1
        for (s, _), (prod, has) in dp.items():
            if s == k and has and prod <= limit:
                if prod > best:
                    best = prod
        return best


