import random, math

def brute(arr):
    n=len(arr)
    best=-1e18
    for i in range(n):
        X_i, H_i=arr[i]
        for j in range(i+1,n):
            X_j,H_j=arr[j]
            val=(H_i*X_j - X_i*H_j)/(X_j-X_i)
            if val>best:
                best=val
    return best

def consecutive(arr):
    n=len(arr)
    best=-1e18
    for i in range(n-1):
        X_i,H_i=arr[i]
        X_j,H_j=arr[i+1]
        val=(H_i*X_j - X_i*H_j)/(X_j-X_i)
        if val>best:
            best=val
    return best

