from functools import lru_cache

def solve():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    it = iter(input_data)
    N = int(next(it)); M = int(next(it)); L = int(next(it))
    vals = []
    for _ in range(N): vals.append(int(next(it)))
    for _ in range(M): vals.append(int(next(it)))
    for _ in range(L): vals.append(int(next(it)))
    total = N+M+L
    pow3 = [1]
    for i in range(total): pow3.append(pow3[-1]*3)
    # initial state
    init_state = 0
    for i in range(total):
        if i < N: loc = 0
        elif i < N+M: loc = 1
        else: loc = 2
        init_state += loc*pow3[i]
    sys.setrecursionlimit(1000000)
    from functools import lru_cache
    @lru_cache(None)
    def dfs(state, turn):
        # check if current player has any card
        has_move = False
        for i in range(total):
            loc = (state // pow3[i]) % 3
            if loc == turn:
                has_move = True
                break
        if not has_move:
            return False
        # iterate through all cards
        for i in range(total):
            loc_i = (state // pow3[i]) % 3
            if loc_i != turn:
                continue
            # option no take
            state_no_take = state + (2-loc_i)*pow3[i]
            if not dfs(state_no_take, 1-turn):
                return True
            # iterate j that can be taken
            val_i = vals[i]
            for j in range(total):
                loc_j = (state // pow3[j]) % 3
                if loc_j != 2:
                    continue
                if vals[j] < val_i:
                    # take j
                    state_take = state + (2-loc_i)*pow3[i] + (turn-2)*pow3[j]
                    # turn-2 is 0-2=-2? Wait, new loc of j: turn
                    # old loc_j is 2, new loc turn.
                    state_take = state + (2-loc_i)*pow3[i] + (turn-2)*pow3[j]
                    if not dfs(state_take, 1-turn):
                        return True
        return False
    result = dfs(init_state, 0)
    print('Takahashi' if result else 'Aoki')

if __name__ == '__main__':
    solve()

