            continue
        x = pow(a, d, n)
        if x == 1 or x == n-1:
            continue
        for _ in range(s-1):
            x = (x*x) % n
            if x == n-1:
                break
        else:
            return False
    return True

# Pollard‑Rho integer factorisation

def pollard_rho(n: int) -> int:
    if n % 2 == 0:
        return 2
    if n % 3 == 0:
        return 3
    while True:
        c = random.randrange(1, n)
        f = lambda x: (pow(x, 2, n) + c) % n
        x, y, d = 2, 2, 1
        while d == 1:
            x = f(x)
            y = f(f(y))
            d = math.gcd(abs(x - y), n)
        if d != n:
            return d


def factor(n: int, res: dict = None) -> dict:
    if res is None:
        res = {}
    if n == 1:
        return res
    if is_probable_prime(n):
        res[n] = res.get(n, 0) + 1
        return res
    d = pollard_rho(n)
    factor(d, res)
    factor(n // d, res)
    return res

# Generate all divisors from prime factorisation

def gen_divisors(prime_pow):
    primes = list(prime_pow.keys())
    exps = [prime_pow[p] for p in primes]
    res = [1]
    for p, e in zip(primes, exps):
        cur = []
        powp = 1
        for _ in range(e+1):
            for val in res:
                cur.append(val * powp)
            powp *= p
        res = cur
    return res

# Find one solution (x,y) such that x^3 - y^3 = N

