def count_beautiful_upto(X):
    if X<=0:
        return 0
    digs = list(map(int,str(X)))
    n = len(digs)
    from functools import lru_cache
    @lru_cache(None)
    def dp_no_zero(pos,tight,started):
        if pos==n:
            return 1 if started else 0
        limit = digs[pos] if tight else 9
        res=0
        for d in range(0,limit+1):
            ntight = tight and d==limit
            if not started:
                if d==0:
                    res+=dp_no_zero(pos+1,ntight,False)
                else:
                    res+=dp_no_zero(pos+1,ntight,True)
            else:
                if d==0:
                    continue
                res+=dp_no_zero(pos+1,ntight,True)
        return res
    f1=dp_no_zero(0,True,False)
    f2=0
    for s in range(1,82):
        @lru_cache(None)
        def dp(pos,tight,started,sum_sofar,prod_mod):
            if sum_sofar> s:
                return 0
            if pos==n:
                return 1 if started and sum_sofar==s and prod_mod==0 else 0
            limit = digs[pos] if tight else 9
            res=0
            for d in range(0,limit+1):
                ntight = tight and d==limit
                if not started:
                    if d==0:
                        res+=dp(pos+1,ntight,False,sum_sofar,prod_mod)
                    else:
                        res+=dp(pos+1,ntight,True,sum_sofar+d,(d % s))
                else:
                    if d==0:
                        continue
                    res+=dp(pos+1,ntight,True,sum_sofar+d,(prod_mod*d)%s)
            return res
        f2+=dp(0,True,False,0,0)
    return X - f1 + f2

