def compute_min_cost(Ps, lam):
    total=0
    for p in Ps:
        k=(lam//p + 1)//2
        total+=k*k*p
    return total

def kth_alternating(n,k):
    odds=[x for x in range(1,n+1) if x%2==1]
    evens=[x for x in range(1,n+1) if x%2==0]
    o=len(odds); e=len(evens)
    memo={}
    def f(o,e,prev):
        if o+e==0:
            return 1
        key=(o,e,prev)
        if key in memo:
            return memo[key]
        if prev==0:
            res=o*f(o-1,e,1)
        else:
            res=e*f(o,e-1,0)
        memo[key]=res
        return res
    all_sorted=sorted(odds+evens)
    total=0
    for c in all_sorted:
        new_o=o-(c%2==1)
        new_e=e-(c%2==0)
        total+=f(new_o,new_e,c%2)
    if k>total:
        return []
    result=[]
    prev=None
    o=len(odds); e=len(evens)
    for pos in range(n):
        if pos==0:
            options=sorted(odds+evens)
        else:
            allowed=1-prev
            options=odds if allowed==1 else evens
        for c in options:
            if c%2==1 and odds.count(c)==0: continue
            if c%2==0 and evens.count(c)==0: continue
            new_o=o-(c%2==1)
            new_e=e-(c%2==0)
            count=f(new_o,new_e,c%2)
            if k<=count:
                result.append(c)
                if c%2==1: odds.remove(c)
                else: evens.remove(c)
                o=new_o; e=new_e; prev=c%2
                break
            else:
                k-=count
    return result

