from collections import defaultdict

def possible(N,K,edges):
    V=N*K
    adj=[[] for _ in range(V+1)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)
    import sys
    sys.setrecursionlimit(500000)
    def dfs(u,p):
        lens=[]
        for v in adj[u]:
            if v==p: continue
            res=dfs(v,u)
            if res==-1:
                return -1
            if res>0:
                if res> K-1:
                    return -1
                lens.append(res)
            # res==0 means child subtree already closed
        # pairing
        if not lens:
            return 1
        lens.sort()
        used=[False]*len(lens)
        i=0; j=len(lens)-1
        while i<j:
            while i<j and used[i]: i+=1
            while i<j and used[j]: j-=1
            if i>=j: break
            if lens[i]+lens[j]==K-1:
                used[i]=used[j]=True
                i+=1; j-=1
            elif lens[i]+lens[j] < K-1:
                i+=1
            else:
                j-=1
        remain=[lens[idx] for idx in range(len(lens)) if not used[idx]]
        if len(remain)>1:
            return -1
        if len(remain)==0:
            return 1
        l=remain[0]
        if l+1==K:
            return 0
        else:
            return l+1
    res=dfs(1,0)
    return res==0

