#!/usr/bin/env python3
import sys
from functools import lru_cache


def solve():
    import sys
    H,W,K = map(int, sys.stdin.readline().split())
    grid = [sys.stdin.readline().strip() for _ in range(H)]
    # map each empty cell to an index
    idx = [[-1]*W for _ in range(H)]
    empty = []
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.':
                idx[i][j] = len(empty)
                empty.append((i,j))
    N = len(empty)
    # adjacency list
    adj = [[] for _ in range(N)]
    dirs = [(-1,0),(1,0),(0,-1),(0,1)]
    for p, (i,j) in enumerate(empty):
        for di,dj in dirs:
            ni, nj = i+di, j+dj
            if 0 <= ni < H and 0 <= nj < W and grid[ni][nj]=='.':
                adj[p].append(idx[ni][nj])
    sys.setrecursionlimit(10000)

    @lru_cache(maxsize=None)
    def dfs(pos, visited_mask, steps_left):
        if steps_left == 0:
            return 1
        total = 0
        for nb in adj[pos]:
            if not (visited_mask >> nb) & 1:
                total += dfs(nb, visited_mask | (1 << nb), steps_left - 1)
        return total

    ans = 0
    for s in range(N):
        ans += dfs(s, 1 << s, K)
    print(ans)

if __name__=='__main__':
    solve()

