import random, sys
from typing import Optional

class Node:
    __slots__ = ('key','end','color','prio','left','right')
    def __init__(self, key:int, end:int, color:int):
        self.key=key
        self.end=end
        self.color=color
        self.prio=random.randint(1,1<<30)
        self.left=None
        self.right=None

# split node by key. returns (l,r) such that l keys <= key, r > key.
def split(node:Optional[Node], key:int):
    if node is None:
        return (None,None)
    if key < node.key:
        l, r = split(node.left, key)
        node.left = r
        return (l, node)
    else:
        l, r = split(node.right, key)
        node.right = l
        return (node, r)

# merge two nodes assuming all keys in a <= keys in b

def merge(a:Optional[Node], b:Optional[Node]):
    if a is None:
        return b
    if b is None:
        return a
    if a.prio > b.prio:
        a.right = merge(a.right, b)
        return a
    else:
        b.left = merge(a, b.left)
        return b

# insert new_node into tree
def insert(node:Optional[Node], new_node:Node):
    l,r = split(node, new_node.key)
    return merge(merge(l,new_node), r)

# delete node with key from tree
def delete(node:Optional[Node], key:int):
    l,r = split(node, key-1)
    m, r2 = split(r, key)
    # m is node with key
    return merge(l, r2)

# predecessor of <= key
def predecessor(node:Optional[Node], key:int):
    res=None
    while node:
        if node.key <= key:
            res=node
            node=node.right
        else:
            node=node.left
    return res

# successor of > key

def successor(node:Optional[Node], key:int):
    res=None
    while node:
        if node.key > key:
            res=node
            node=node.left
        else:
            node=node.right
    return res

# main process

def solve(inp:str):
    data=list(map(int, inp.strip().split()))
    it=iter(data)
    N=next(it); Q=next(it)
    # initialize intervals 1..N with each cell
    root=None
    counts=[0]*(N+1)
    for i in range(1,N+1):
        node=Node(i,i,i)
        root=merge(root,node)
        counts[i]+=1
    outputs=[]
