"""
Solution for: longest-common-prefix-of-k-strings-after-removal
Problem ID: lcb_3784

Implement the function below.
"""

from typing import List, Dict

class TrieNode:
    __slots__ = ('children', 'count', 'depth')
    def __init__(self, depth: int):
        self.children: Dict[str, 'TrieNode'] = {}
        self.count: int = 0
        self.depth: int = depth

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        # Edge case: if after removal fewer than k strings remain
        if n - 1 < k:
            return [0] * n
        root = TrieNode(0)
        nodes = [root]  # list of all nodes
        max_depth = 0
        # Build trie and increment counts
        for w in words:
            cur = root
            for ch in w:
                if ch not in cur.children:
                    new_node = TrieNode(cur.depth + 1)
                    cur.children[ch] = new_node
                    nodes.append(new_node)
                cur = cur.children[ch]
                cur.count += 1
                if cur.depth > max_depth:
                    max_depth = cur.depth
        # arrays for depth info
        max_count_at_depth = [0] * (max_depth + 1)
        num_k_nodes_at_depth = [0] * (max_depth + 1)
        for node in nodes[1:]:  # skip root? root depth 0 handled separately
            d = node.depth
            cnt = node.count
            if cnt > max_count_at_depth[d]:
