from typing import List

# Trie node definition
class TrieNode:
    __slots__ = ('children', 'count')
    def __init__(self):
        self.children: dict[str, 'TrieNode'] = {}
        self.count: int = 0


def longestCommonPrefix(words: List[str], k: int) -> List[int]:
    n = len(words)
    if n - 1 < k:
        return [0] * n
    # Build trie
    root = TrieNode()
    for w in words:
        node = root
        for ch in w:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
            node.count += 1
    # Precompute for each depth the maximum count
    max_depth = max((len(w) for w in words), default=0)
    max_counts = [0] * (max_depth + 1)
    # DFS to collect counts per depth
    def dfs(node: TrieNode, depth: int):
        if depth > max_depth:
            return
        max_counts[depth] = max(max_counts[depth], node.count)
        for child in node.children.values():
            dfs(child, depth + 1)
    for child in root.children.values():
        dfs(child, 1)
    # For root depth 0
    max_counts[0] = len(words)
    # Compute global answer depth
    global_depth = 0
    for d in range(max_depth, -1, -1):
        if max_counts[d] >= k:
            global_depth = d
            break
    # For each word, compute answer
    res = [0] * n
    for idx, w in enumerate(words):
        # walk to global_depth
        node = root
        depth = 0
        for ch in w:
            if depth == global_depth:
                break
            if ch not in node.children:
                node = None
                break
            node = node.children[ch]
            depth += 1
        if node is None or depth < global_depth:
            res[idx] = global_depth
            continue
        if node.count > k:
            res[idx] = global_depth
            continue
        # If count == k, need to ensure other siblings also have k
        # Count nodes at that depth with count == k
        # Simple approach: traverse all nodes at depth global_depth
        count_k = 0
        def count_k_nodes(n: TrieNode, d: int):
            nonlocal count_k
            if d == global_depth:
                if n.count == k:
                    count_k += 1
                return
            for c in n.children.values():
                count_k_nodes(c, d + 1)
        count_k_nodes(root, 0)
        if count_k > 1:
            res[idx] = global_depth
        else:
            # Find previous depth with max_counts[prev] > k
            prev = 0
            for d in range(global_depth - 1, -1, -1):
                if max_counts[d] > k or (max_counts[d] == k and sum(1 for node in [root] + list(root.children.values()) if node.count == k) > 1):
                    prev = d
                    break
            res[idx] = prev
    return res

