        random.shuffle(all_cells)
        pre=[]
        for idx in range(M):
            i,j=all_cells[idx]
            c=random.choice(['B','W'])
            pre.append((i,j,c))
        b=brute(N, pre)
        g=can(N, pre)
        if b!=g:
            print('Mismatch',N,pre,b,g)
            raise SystemExit
