class Solution:
    def countWinningSequences(self, s: str) -> int:
        mod = 10**9 + 7
        n = len(s)
        # map chars to indices
        idx_map = {'F': 0, 'W': 1, 'E': 2}
        # winning relation: key beats win_map[key]
        win_map = {'F': 'E', 'E': 'W', 'W': 'F'}
        # size of diff dimension
        offset = n
        size = 2 * n + 1
        # dp[prev][diff_index]
        dp = [[0] * size for _ in range(3)]
        # first round
        alice0 = s[0]
        for m in range(3):
            if m == idx_map[alice0]:
                delta = 0
            elif win_map[chr(ord('A') + m)] == alice0:
                # Bob's move beats Alice
                delta = 1
            else:
                # Alice beats Bob
                delta = -1
            dp[m][delta + offset] = (dp[m][delta + offset] + 1) % mod
        # iterate remaining rounds
        for i in range(1, n):
            alice = s[i]
            newdp = [[0] * size for _ in range(3)]
            for prev in range(3):
                for idx in range(size):
                    ways = dp[prev][idx]
                    if ways == 0:
                        continue
                    for nxt in range(3):
                        if nxt == prev:
