                        new_idx = idx + delta
                        newdp[nxt][new_idx] = (newdp[nxt][new_idx] + ways) % mod
            dp = newdp
        # compute answer: sum over states with diff>0
        ans = 0
        for prev in range(3):
            for idx in range(offset + 1, size):
                ans = (ans + dp[prev][idx]) % mod
        return ans

