import itertools, math

def brute(n,m,k):
    count=0
    for arr in itertools.product(range(1,m+1), repeat=n):
        if sum(arr[i]==arr[i+1] for i in range(n-1))==k:
            count+=1
    return count

def comb_formula(n,m,k):
    mod=10**9+7
    if k>n-1: return 0
    # handle particular constraints
    from math import comb
    if m==0: return 0
    # compute combination via math.comb for small test
    return comb(n-1,k)*m*(m-1)**(n-k-1)

for n in range(1,7):
    for m in range(1,4):
        for k in range(n):
            if n<=6:
                b=brute(n,m,k)
                f=comb_formula(n,m,k)
                if b!=f:
                    print(n,m,k,b,f)
